import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Problema del primo accadere di un evento","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/l_calcolo-delle-probabilita/le/leafba.md","filePath":"lezioni/l_calcolo-delle-probabilita/le/leafba.md"}`),a={name:`lezioni/l_calcolo-delle-probabilita/le/leafba.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="problema-del-primo-accadere-di-un-evento" tabindex="-1">Problema del primo accadere di un evento <a class="header-anchor" href="#problema-del-primo-accadere-di-un-evento" aria-label="Permalink to “Problema del primo accadere di un evento”">​</a></h1><p>Consideriamo un gioco aleatorio, ad esempio l&#39;estrazione di un numero al lotto in una particolare ruota, e chiediamoci qual è la probabilità che l&#39;evento &quot;uscita del numero&quot; accada alla prima estrazione, alla seconda, alla terza, ... eccetera.</p><p>Se consideriamo la variabile aleatoria &quot;l&#39;evento si verifica la prima volta all&#39;<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span>-ma prova&quot; con <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>n</mi><mo>=</mo><mn>1</mn><mo separator="true">,</mo><mn>2</mn><mo separator="true">,</mo><mn>3</mn><mo separator="true">,</mo><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi></mrow><annotation encoding="application/x-tex">n=1,2,3,...</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">3</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">...</span></span></span></span>, avremo una variabile la cui distribuzione di probabilità è detta <strong>distribuzione geometrica</strong>.</p><blockquote><p><strong>Esempi:</strong></p><p>Trovare le probabilità di uscita di &quot;testa&quot; al primo, secondo, terzo, ... <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span>-esimo lancio di una moneta</p><p>Trovare le probabilità di uscita del numero 3 nel lancio di un dado al primo, al secondo, all&#39;<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span>-esimo lancio</p><p>Trovare le probabilità di uscita del numero 1 sulla ruota di Bari alla prima, alla seconda, alla <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span>-esima estrazione</p></blockquote>`,4)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};